'use client'

import { CalendarDaysIcon } from 'lucide-react'
import type React from 'react'
import { useState } from 'react'
import { Button } from '@/components/ui/button'
import { Calendar } from '@/components/ui/calendar'
import { Popover, PopoverPopup } from '@/components/ui/popover'
import { PropertyPopoverTrigger, PropertyTriggerButton } from '../property-trigger'

export type DatePropertyDropdownPlacement = Pick<
  React.ComponentProps<typeof PopoverPopup>,
  'align' | 'alignOffset' | 'side' | 'sideOffset'
>

export interface DatePropertyActionContext {
  date: Date | null
  previousValue: string | null
}

export interface DatePropertyProps {
  value: string | null
  action?: (value: string | null, context: DatePropertyActionContext) => void
  allowClear?: boolean
  ariaLabel?: string
  calendarProps?: Omit<
    React.ComponentProps<typeof Calendar>,
    'defaultMonth' | 'mode' | 'onSelect' | 'selected'
  >
  className?: string
  clearLabel?: string
  fallback?: string
  disabled?: boolean
  dropdownPlacement?: DatePropertyDropdownPlacement
  locale?: string
  readOnly?: boolean
  serializeDate?: (date: Date) => string
  timeZone?: string
  onValueChange?: (value: string | null) => void
}

export function DateProperty({
  action,
  allowClear = true,
  ariaLabel,
  calendarProps,
  className,
  clearLabel = 'Clear date',
  disabled = false,
  dropdownPlacement,
  fallback = 'No date',
  locale = 'en-US',
  onValueChange,
  readOnly = false,
  serializeDate = serializeDatePropertyValue,
  timeZone = 'UTC',
  value,
}: Readonly<DatePropertyProps>) {
  const [open, setOpen] = useState(false)
  const selectedDate = parseDatePropertyValue(value)
  const accessibleLabel = ariaLabel ?? 'Date'
  const canUpdate = Boolean(action ?? onValueChange)

  const handleChange = (nextValue: string | null, date: Date | null) => {
    if (nextValue === value) {
      setOpen(false)
      return
    }

    if (action) {
      action(nextValue, {
        date,
        previousValue: value,
      })
    } else {
      onValueChange?.(nextValue)
    }
    setOpen(false)
  }

  if (readOnly || !canUpdate) {
    return (
      <DatePropertyButton
        className={className}
        fallback={fallback}
        locale={locale}
        timeZone={timeZone}
        value={value}
      />
    )
  }

  const label = formatDateProperty(value, fallback, locale, timeZone)

  return (
    <Popover onOpenChange={setOpen} open={open}>
      <PropertyPopoverTrigger
        aria-label={`${accessibleLabel}: ${label}`}
        className={className}
        disabled={disabled}
      >
        <DatePropertyContent label={label} />
      </PropertyPopoverTrigger>
      <PopoverPopup align="start" className="w-auto" side="bottom" {...dropdownPlacement}>
        <Calendar
          defaultMonth={selectedDate ?? undefined}
          mode="single"
          selected={selectedDate ?? undefined}
          onSelect={(date) => {
            if (!date) return
            handleChange(serializeDate(date), date)
          }}
          {...calendarProps}
        />
        {allowClear ? (
          <div className="border-t p-2">
            <Button
              className="w-full justify-start"
              size="sm"
              type="button"
              variant="ghost"
              onClick={() => handleChange(null, null)}
            >
              {clearLabel}
            </Button>
          </div>
        ) : null}
      </PopoverPopup>
    </Popover>
  )
}

export function DatePropertyButton({
  className,
  fallback = 'No date',
  locale = 'en-US',
  timeZone = 'UTC',
  value,
}: Readonly<Pick<DatePropertyProps, 'className' | 'fallback' | 'locale' | 'timeZone' | 'value'>>) {
  const label = formatDateProperty(value, fallback, locale, timeZone)

  return (
    <PropertyTriggerButton className={className}>
      <DatePropertyContent label={label} />
    </PropertyTriggerButton>
  )
}

function DatePropertyContent({ label }: Readonly<{ label: string }>) {
  return (
    <>
      <CalendarDaysIcon aria-hidden />
      <span className="truncate">{label}</span>
    </>
  )
}

export function formatDateProperty(
  value: string | null,
  fallback: string,
  locale: string,
  timeZone: string,
): string {
  const date = parseDatePropertyValue(value)
  if (!date) return fallback
  return new Intl.DateTimeFormat(locale, {
    dateStyle: 'medium',
    timeZone,
  }).format(date)
}

export function parseDatePropertyValue(value: string | null): Date | null {
  if (!value) return null
  const date = new Date(value)
  if (Number.isNaN(date.getTime())) return null
  return date
}

export function serializeDatePropertyValue(date: Date): string {
  return new Date(Date.UTC(date.getFullYear(), date.getMonth(), date.getDate(), 12)).toISOString()
}

'use client'

import { UserPlusIcon } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Select, SelectItem, SelectPopup } from '@/components/ui/select'
import { PropertySelectTrigger, PropertyTriggerButton } from '../property-trigger'
import type { PersonPropertyDropdownPlacement, PersonPropertyOption } from './person-property'

export interface MultiPersonPropertyActionContext<TValue extends string = string> {
  options: readonly PersonPropertyOption<TValue>[]
  previousValue: readonly TValue[]
}

export interface MultiPersonPropertyProps<TValue extends string = string> {
  value: readonly TValue[]
  options: readonly PersonPropertyOption<TValue>[]
  action?: (value: readonly TValue[], context: MultiPersonPropertyActionContext<TValue>) => void
  ariaLabel?: string
  className?: string
  disabled?: boolean
  dropdownPlacement?: PersonPropertyDropdownPlacement
  maxVisible?: number
  placeholder?: string
  readOnly?: boolean
  onValueChange?: (value: readonly TValue[]) => void
}

export function MultiPersonProperty<TValue extends string = string>({
  action,
  ariaLabel,
  className,
  disabled = false,
  dropdownPlacement,
  maxVisible = 3,
  onValueChange,
  options,
  placeholder = 'No people',
  readOnly = false,
  value,
}: Readonly<MultiPersonPropertyProps<TValue>>) {
  const resolvedOptions = options.map((option) => ({ ...option, label: option.name }))
  const selectedOptions = value.map((personValue) => findPersonOption(resolvedOptions, personValue))
  const accessibleLabel = ariaLabel ?? 'People'
  const canUpdate = Boolean(action ?? onValueChange)

  if (readOnly || !canUpdate) {
    return (
      <MultiPersonPropertyButton
        className={className}
        maxVisible={maxVisible}
        options={selectedOptions}
        placeholder={placeholder}
      />
    )
  }

  return (
    <Select
      itemToStringLabel={(option) => option.name}
      itemToStringValue={(option) => option.value}
      items={resolvedOptions}
      multiple
      value={selectedOptions}
      onValueChange={(nextOptions) => {
        const nextValue = nextOptions.map((option) => option.value)
        if (areValuesEqual(value, nextValue)) return

        if (action) {
          action(nextValue, { options: nextOptions, previousValue: value })
          return
        }
        onValueChange?.(nextValue)
      }}
    >
      <PropertySelectTrigger
        aria-label={`${accessibleLabel}: ${formatPersonLabels(selectedOptions, placeholder)}`}
        disabled={disabled}
        className={className}
      >
        <MultiPersonPropertyContent
          maxVisible={maxVisible}
          options={selectedOptions}
          placeholder={placeholder}
        />
      </PropertySelectTrigger>
      <SelectPopup alignItemWithTrigger={false} {...dropdownPlacement}>
        {resolvedOptions.map((option) => (
          <SelectItem
            aria-label={option.name}
            className="data-selected:bg-accent"
            key={option.value}
            value={option}
          >
            <PersonOptionContent option={option} />
          </SelectItem>
        ))}
      </SelectPopup>
    </Select>
  )
}

export function MultiPersonPropertyButton<TValue extends string = string>({
  className,
  maxVisible = 3,
  options,
  placeholder = 'No people',
}: Readonly<{
  className?: string
  maxVisible?: number
  options: readonly PersonPropertyOption<TValue>[]
  placeholder?: string
}>) {
  return (
    <PropertyTriggerButton className={className}>
      <MultiPersonPropertyContent
        maxVisible={maxVisible}
        options={options}
        placeholder={placeholder}
      />
    </PropertyTriggerButton>
  )
}

function MultiPersonPropertyContent<TValue extends string>({
  maxVisible,
  options,
  placeholder,
}: Readonly<{
  maxVisible: number
  options: readonly PersonPropertyOption<TValue>[]
  placeholder: string
}>) {
  if (options.length === 0) {
    return (
      <span className="flex min-w-0 items-center gap-1.5 text-muted-foreground">
        <UserPlusIcon aria-hidden />
        <span className="truncate">{placeholder}</span>
      </span>
    )
  }

  const visibleOptions = options.slice(0, Math.max(1, maxVisible))
  const hiddenCount = options.length - visibleOptions.length

  return (
    <span className="flex min-w-0 items-center gap-1.5">
      <span className="flex shrink-0 -space-x-1">
        {visibleOptions.map((option) => (
          <PersonAvatar key={option.value} option={option} />
        ))}
      </span>
      <span className="truncate">{formatPersonLabels(visibleOptions, placeholder)}</span>
      {hiddenCount > 0 ? (
        <span className="text-muted-foreground text-xs">+{hiddenCount}</span>
      ) : null}
    </span>
  )
}

function PersonOptionContent<TValue extends string>({
  option,
}: Readonly<{ option: PersonPropertyOption<TValue> }>) {
  return (
    <span className="flex min-w-0 items-center gap-1.5">
      <PersonAvatar option={option} />
      <span className="min-w-0">
        <span className="block truncate">{option.name}</span>
        {option.description ? (
          <span className="block truncate text-muted-foreground text-xs">{option.description}</span>
        ) : null}
      </span>
    </span>
  )
}

function PersonAvatar<TValue extends string>({
  option,
}: Readonly<{ option: PersonPropertyOption<TValue> }>) {
  return (
    <Avatar className="size-6 border border-secondary text-[0.625rem]">
      {option.avatar?.src ? <AvatarImage alt="" src={option.avatar.src} /> : null}
      <AvatarFallback>{option.avatar?.fallback ?? getInitials(option.name)}</AvatarFallback>
    </Avatar>
  )
}

function findPersonOption<TValue extends string>(
  options: readonly PersonPropertyOption<TValue>[],
  value: TValue,
): PersonPropertyOption<TValue> {
  return options.find((option) => option.value === value) ?? { name: value, value }
}

function formatPersonLabels<TValue extends string>(
  options: readonly PersonPropertyOption<TValue>[],
  placeholder: string,
): string {
  return options.length > 0 ? options.map((option) => option.name).join(', ') : placeholder
}

function areValuesEqual<TValue extends string>(
  current: readonly TValue[],
  next: readonly TValue[],
): boolean {
  return current.length === next.length && current.every((value, index) => value === next[index])
}

function getInitials(label: string): string {
  return label
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join('')
    .toUpperCase()
}

'use client'

import { UserPlusIcon, XIcon } from 'lucide-react'
import { Avatar, AvatarFallback, AvatarImage } from '@/components/ui/avatar'
import { Select, SelectItem, SelectPopup } from '@/components/ui/select'
import { cn } from '../../../lib/utils'
import { PropertySelectTrigger, PropertyTriggerButton } from '../property-trigger'

export interface PersonPropertyAvatar {
  fallback?: string
  src?: string
}

export interface PersonPropertyOption<TValue extends string = string> {
  value: TValue
  avatar?: PersonPropertyAvatar
  description?: string
  name: string
}

export type PersonPropertyDropdownPlacement = Pick<
  React.ComponentProps<typeof SelectPopup>,
  'align' | 'alignItemWithTrigger' | 'alignOffset' | 'side' | 'sideOffset'
>

export interface PersonPropertyActionContext<TValue extends string = string> {
  option: PersonPropertyOption<TValue> | null
  previousValue: TValue | null
}

export interface PersonPropertyProps<TValue extends string = string> {
  value: TValue | null
  options: readonly PersonPropertyOption<TValue>[]
  action?: (value: TValue | null, context: PersonPropertyActionContext<TValue>) => void
  allowClear?: boolean
  ariaLabel?: string
  className?: string
  clearLabel?: string
  disabled?: boolean
  dropdownPlacement?: PersonPropertyDropdownPlacement
  placeholder?: string
  readOnly?: boolean
  onValueChange?: (value: TValue | null) => void
}

interface ClearPersonOption {
  clear: true
  label: string
  value: null
}

type ResolvedPersonPropertyOption<TValue extends string> = PersonPropertyOption<TValue> & {
  label: string
}

type PersonSelectOption<TValue extends string> = PersonPropertyOption<TValue> | ClearPersonOption

type ResolvedPersonSelectOption<TValue extends string> =
  | ResolvedPersonPropertyOption<TValue>
  | ClearPersonOption

export function PersonProperty<TValue extends string = string>({
  action,
  allowClear = true,
  ariaLabel,
  className,
  clearLabel = 'Clear person',
  disabled = false,
  dropdownPlacement,
  onValueChange,
  options,
  placeholder = 'Unassigned',
  readOnly = false,
  value,
}: Readonly<PersonPropertyProps<TValue>>) {
  const resolvedOptions = options.map(resolvePersonOption)
  const selectedOption = value ? findPersonOption(resolvedOptions, value) : null
  const selectOptions: readonly ResolvedPersonSelectOption<TValue>[] = allowClear
    ? [...resolvedOptions, { clear: true, label: clearLabel, value: null }]
    : resolvedOptions
  const accessibleLabel = ariaLabel ?? 'Person'
  const canUpdate = Boolean(action ?? onValueChange)

  if (readOnly || !canUpdate) {
    return (
      <PersonPropertyButton
        className={className}
        option={selectedOption}
        placeholder={placeholder}
      />
    )
  }

  return (
    <Select
      itemToStringLabel={(option) => getPersonOptionName(option)}
      itemToStringValue={(option) => option.value ?? ''}
      items={selectOptions}
      onValueChange={(option) => {
        if (option && option.value !== value) {
          const nextOption = isClearPersonOption(option) ? null : option
          if (action) {
            action(option.value, {
              option: nextOption,
              previousValue: value,
            })
            return
          }
          onValueChange?.(option.value)
        }
      }}
      value={selectedOption}
    >
      <PropertySelectTrigger
        aria-label={`${accessibleLabel}: ${selectedOption?.name ?? placeholder}`}
        disabled={disabled}
        className={className}
      >
        <PersonPropertyContent option={selectedOption} placeholder={placeholder} />
      </PropertySelectTrigger>
      <SelectPopup alignItemWithTrigger={false} {...dropdownPlacement}>
        {selectOptions.map((option) => (
          <SelectItem
            aria-label={getPersonOptionName(option)}
            className="data-selected:bg-accent"
            key={option.value ?? '__clear-person__'}
            value={option}
          >
            {isClearPersonOption(option) ? (
              <span className="flex min-w-0 items-center gap-1.5 text-muted-foreground">
                <XIcon aria-hidden />
                <span className="truncate">{option.label}</span>
              </span>
            ) : (
              <PersonPropertyContent option={option} placeholder={placeholder} showDescription />
            )}
          </SelectItem>
        ))}
      </SelectPopup>
    </Select>
  )
}

function isClearPersonOption<TValue extends string>(
  option: PersonSelectOption<TValue>,
): option is ClearPersonOption {
  return 'clear' in option
}

function getPersonOptionName<TValue extends string>(option: PersonSelectOption<TValue>): string {
  return isClearPersonOption(option) ? option.label : option.name
}

function resolvePersonOption<TValue extends string>(
  option: PersonPropertyOption<TValue>,
): ResolvedPersonPropertyOption<TValue> {
  return { ...option, label: option.name }
}

export function PersonPropertyButton<TValue extends string = string>({
  className,
  option,
  placeholder = 'Unassigned',
}: Readonly<{
  className?: string
  option: PersonPropertyOption<TValue> | null
  placeholder?: string
}>) {
  return (
    <PropertyTriggerButton className={className}>
      <PersonPropertyContent option={option} placeholder={placeholder} />
    </PropertyTriggerButton>
  )
}

function PersonPropertyContent<TValue extends string = string>({
  option,
  placeholder,
  showDescription = false,
}: Readonly<{
  option: PersonPropertyOption<TValue> | null
  placeholder: string
  showDescription?: boolean
}>) {
  if (!option) {
    return (
      <span className="flex min-w-0 items-center gap-1.5 text-muted-foreground">
        <UserPlusIcon aria-hidden />
        <span className="truncate">{placeholder}</span>
      </span>
    )
  }

  return (
    <span className="flex min-w-0 items-center gap-1.5">
      <Avatar className={cn(showDescription ? 'size-8 text-xs' : 'size-4 text-[0.625rem]')}>
        {option.avatar?.src ? <AvatarImage alt="" src={option.avatar.src} /> : null}
        <AvatarFallback>{option.avatar?.fallback ?? getInitials(option.name)}</AvatarFallback>
      </Avatar>
      <span className="min-w-0">
        <span className="block truncate">{option.name}</span>
        {showDescription && option.description ? (
          <span className="block truncate text-muted-foreground text-xs">{option.description}</span>
        ) : null}
      </span>
    </span>
  )
}

function findPersonOption<TValue extends string>(
  options: readonly PersonPropertyOption<TValue>[],
  value: TValue,
): PersonPropertyOption<TValue> {
  const selectedOption = options.find((option) => option.value === value)
  if (selectedOption) return selectedOption
  return {
    name: value,
    value,
  }
}

function getInitials(label: string): string {
  return label
    .split(/\s+/)
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0])
    .join('')
    .toUpperCase()
}

'use client'

import type React from 'react'
import { Select, SelectItem, SelectPopup } from '@/components/ui/select'
import { cn } from '../../../lib/utils'
import { PropertySelectTrigger, PropertyTriggerButton } from '../property-trigger'

export type SelectPropertyIcon = React.ComponentType<React.SVGProps<SVGSVGElement>>

export interface SelectPropertyOption<TValue extends string = string> {
  id: TValue
  label: string
  icon?: SelectPropertyIcon
  iconClassName?: string
}

type ResolvedSelectPropertyOption<TValue extends string = string> = SelectPropertyOption<TValue> & {
  value: TValue
}

export type SelectPropertyDropdownPlacement = Pick<
  React.ComponentProps<typeof SelectPopup>,
  'align' | 'alignItemWithTrigger' | 'alignOffset' | 'side' | 'sideOffset'
>

export interface SelectPropertyActionContext<TValue extends string = string> {
  option: SelectPropertyOption<TValue>
  previousValue: TValue
}

export interface SelectPropertyProps<TValue extends string = string> {
  value: TValue
  options: readonly SelectPropertyOption<TValue>[]
  action?: (value: TValue, context: SelectPropertyActionContext<TValue>) => void
  ariaLabel?: string
  className?: string
  disabled?: boolean
  dropdownClassName?: string
  dropdownPlacement?: SelectPropertyDropdownPlacement
  readOnly?: boolean
  onValueChange?: (value: TValue) => void
}

export function SelectProperty<TValue extends string = string>({
  action,
  ariaLabel,
  className,
  disabled = false,
  dropdownClassName,
  dropdownPlacement,
  onValueChange,
  options,
  readOnly = false,
  value,
}: Readonly<SelectPropertyProps<TValue>>) {
  const selectOptions = options.map((option) => ({ ...option, value: option.id }))
  const selectedOption = findSelectOption(selectOptions, value)
  const accessibleLabel = ariaLabel ?? 'Property'
  const canUpdate = Boolean(action ?? onValueChange)

  if (readOnly || !canUpdate) {
    return <SelectPropertyButton className={className} option={selectedOption} />
  }

  return (
    <Select
      itemToStringLabel={(option) => option.label}
      itemToStringValue={(option) => option.value}
      items={selectOptions}
      onValueChange={(option) => {
        if (option && option.value !== value) {
          if (action) {
            action(option.value, {
              option,
              previousValue: value,
            })
            return
          }
          onValueChange?.(option.value)
        }
      }}
      value={selectedOption}
    >
      <PropertySelectTrigger
        aria-label={`${accessibleLabel}: ${selectedOption.label}`}
        disabled={disabled}
        className={className}
      >
        <SelectPropertyContent option={selectedOption} />
      </PropertySelectTrigger>
      <SelectPopup
        alignItemWithTrigger={false}
        className={cn('min-w-56', dropdownClassName)}
        {...dropdownPlacement}
      >
        {selectOptions.map((option) => (
          <SelectItem key={option.value} value={option}>
            <SelectPropertyContent option={option} />
          </SelectItem>
        ))}
      </SelectPopup>
    </Select>
  )
}

export function SelectPropertyButton<TValue extends string = string>({
  className,
  option,
}: Readonly<{
  className?: string
  option: SelectPropertyOption<TValue>
}>) {
  return (
    <PropertyTriggerButton className={className}>
      <SelectPropertyContent option={option} />
    </PropertyTriggerButton>
  )
}

function SelectPropertyContent<TValue extends string = string>({
  option,
}: Readonly<{ option: SelectPropertyOption<TValue> }>) {
  const Icon = option.icon
  return (
    <span className="flex min-w-0 items-center gap-1.5">
      {Icon ? <Icon aria-hidden className={cn(option.iconClassName)} /> : null}
      <span className="truncate">{option.label}</span>
    </span>
  )
}

function findSelectOption<TValue extends string>(
  options: readonly ResolvedSelectPropertyOption<TValue>[],
  value: TValue,
): ResolvedSelectPropertyOption<TValue> {
  const selectedOption = options.find((option) => option.value === value)
  if (selectedOption) return selectedOption
  return {
    id: value,
    label: value,
    value,
  }
}

export {
  StringProperty,
  type StringPropertyActionContext,
  StringPropertyButton,
  type StringPropertyProps,
} from './string-property'

'use client'

import { Input } from '@/components/ui/input'
import { cn } from '../../../lib/utils'
import { PropertyTriggerButton } from '../property-trigger'

export interface StringPropertyActionContext {
  previousValue: string
}

export interface StringPropertyProps {
  value: string
  action?: (value: string, context: StringPropertyActionContext) => void
  ariaLabel?: string
  className?: string
  disabled?: boolean
  placeholder?: string
  readOnly?: boolean
  onValueChange?: (value: string) => void
}

export function StringProperty({
  action,
  ariaLabel,
  className,
  disabled = false,
  onValueChange,
  placeholder = 'No value',
  readOnly = false,
  value,
}: Readonly<StringPropertyProps>) {
  const accessibleLabel = ariaLabel ?? 'String'
  const canUpdate = Boolean(action ?? onValueChange)

  if (readOnly || !canUpdate) {
    return <StringPropertyButton ariaLabel={accessibleLabel} className={className} value={value} />
  }

  return (
    <Input
      aria-label={accessibleLabel}
      className={cn(className)}
      disabled={disabled}
      placeholder={placeholder}
      value={value}
      onValueChange={(nextValue) => {
        if (nextValue === value) return

        if (action) {
          action(nextValue, {
            previousValue: value,
          })
          return
        }

        onValueChange?.(nextValue)
      }}
    />
  )
}

export function StringPropertyButton({
  ariaLabel = 'String',
  className,
  placeholder = 'No value',
  value,
}: Readonly<{
  ariaLabel?: string
  className?: string
  placeholder?: string
  value: string
}>) {
  const label = value || placeholder

  return (
    <PropertyTriggerButton aria-label={`${ariaLabel}: ${label}`} className={cn(className)}>
      <span className={cn('truncate', !value && 'text-muted-foreground')}>{label}</span>
    </PropertyTriggerButton>
  )
}

'use client'

import type React from 'react'
import { Button } from '@/components/ui/button'
import { PopoverTrigger } from '@/components/ui/popover'
import { SelectPrimitive } from '@/components/ui/select'
import { cn } from '../../lib/utils'

export const propertyTriggerButtonClassName =
  'h-8 max-w-full min-w-0 justify-start rounded-md bg-transparent px-2 text-sm shadow-none before:rounded-[calc(var(--radius-md)-1px)] sm:h-8'

export interface PropertyTriggerButtonProps
  extends Omit<React.ComponentProps<typeof Button>, 'size' | 'variant'> { }

export function PropertyTriggerButton({
  className,
  ...props
}: Readonly<PropertyTriggerButtonProps>): React.ReactElement {
  return (
    <Button
      className={cn(propertyTriggerButtonClassName, 'data-popup-open:bg-accent', className)}
      data-slot="property-trigger"
      size="sm"
      variant="ghost"
      {...props}
    />
  )
}

export interface PropertySelectTriggerProps
  extends Omit<SelectPrimitive.Trigger.Props, 'className' | 'render'> {
  className?: string
}

export function PropertySelectTrigger({
  children,
  className,
  ...props
}: Readonly<PropertySelectTriggerProps>): React.ReactElement {
  return (
    <SelectPrimitive.Trigger
      data-slot="property-trigger"
      render={<PropertyTriggerButton className={className} />}
      {...props}
    >
      {children}
    </SelectPrimitive.Trigger>
  )
}

export interface PropertyPopoverTriggerProps
  extends Omit<React.ComponentProps<typeof PopoverTrigger>, 'className' | 'render'> {
  className?: string
}

export function PropertyPopoverTrigger({
  children,
  className,
  ...props
}: Readonly<PropertyPopoverTriggerProps>): React.ReactElement {
  return (
    <PopoverTrigger
      data-slot="property-trigger"
      render={<PropertyTriggerButton className={className} />}
      {...props}
    >
      {children}
    </PopoverTrigger>
  )
}

export const PROPERTY_PRIMITIVE_TYPES = ['select', 'person', 'multi-person', 'date', 'string'] as const

export type PropertyPrimitiveType = (typeof PROPERTY_PRIMITIVE_TYPES)[number]

export interface PropertyDefinition<TType extends PropertyPrimitiveType = PropertyPrimitiveType> {
  id: string
  label: string
  type: TType
}

export interface PropertyValueChange<TValue> {
  definition: PropertyDefinition
  previousValue: TValue
  value: TValue
}
